import sys, math, heapq, bisect, random, itertools
input = sys.stdin.readline
sys.setrecursionlimit(10 ** 5)
ints = lambda : list(map(int, input().split()))
p = 10 ** 9 + 7
inf = 10 ** 20 + 7
alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
p2 = [1]
for i in range(40):
	p2.append(p2[-1] * 2)
for t in range(int(input())):
	n = int(input())
	a = ints()
	if a.count(0):
		if n == 1:
			print(0)
		else:
			print(-1)
		continue
	store = [[] for i in range(32)]
	for x in range(n):
		for i in range(32):
			if a[x] & p2[i]:
				store[i].append(x)
	done = set()
	bitset = set()
	ans = 0
	for i in range(32):
		if store[i]:
			bitset.add(i)
			queue = store[i]
			done = set(store[i])
			ans += p2[i] * (len(store[i]) - 1)
			break
	bits = set()
	for i in queue:
		for j in range(32):
			if a[i] & p2[j]:
				if j not in bitset:
					bitset.add(j)
					bits.add(j)
	b = sorted(bits)
	heapq.heapify(b)
	while b:
		x = heapq.heappop(b)
		while store[x]:
			i = store[x].pop()
			if i not in done:
				heapq.heappush(b, x)
				done.add(i)
				m = x
				for j in range(32):
					if p2[j] & a[i]:
						if j in bitset:
							m = min(m, j)
						else:
							bitset.add(j)
							heapq.heappush(b, j)
				ans += p2[m]
				break
	if len(done) == n:
		print(ans)
	else:
		print(-1)
